package com.primehr.rewardsrecognition.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="rr_nomination_source",uniqueConstraints=@UniqueConstraint(name="uk_rr_nomination_source",columnNames={"agency_id","nomination_id","source_type","source_id"}))
public class RrNominationSource extends RspAuditedEntity{public enum Type{COMPETENCY_PROFILE,PERFORMANCE_OUTCOME,LD_COMPLETION}@Column(name="nomination_id",nullable=false,length=36)private String nominationId;@Enumerated(EnumType.STRING)@Column(name="source_type",nullable=false,length=30)private Type sourceType;@Column(name="source_id",nullable=false,length=36)private String sourceId;@Column(name="source_version",nullable=false)private long sourceVersion;@Column(name="source_fingerprint",nullable=false,length=64)private String sourceFingerprint;@Column(name="source_label",nullable=false,length=500)private String sourceLabel;@Column(name="source_changed_at")private Instant sourceChangedAt;@Column(name="captured_at",nullable=false)private Instant capturedAt;protected RrNominationSource(){}public RrNominationSource(String a,String n,Type t,String id,long v,String fp,String label,Instant changed,Instant captured){super(a);nominationId=requiredText(n,"nominationId");sourceType=java.util.Objects.requireNonNull(t);sourceId=requiredText(id,"sourceId");if(v<0)throw new IllegalArgumentException("sourceVersion cannot be negative");sourceVersion=v;sourceFingerprint=requiredText(fp,"sourceFingerprint");sourceLabel=requiredText(label,"sourceLabel");sourceChangedAt=changed;capturedAt=java.util.Objects.requireNonNull(captured);}public String getNominationId(){return nominationId;}public Type getSourceType(){return sourceType;}public String getSourceId(){return sourceId;}public long getSourceVersion(){return sourceVersion;}public String getSourceFingerprint(){return sourceFingerprint;}public String getSourceLabel(){return sourceLabel;}public Instant getSourceChangedAt(){return sourceChangedAt;}public Instant getCapturedAt(){return capturedAt;}}
